  });

it('P6: tạo đề xuất với so_ho_so trùng phải bị chặn ở tầng ứng dụng, không vỡ 500', async () => {
    await taoDeXuat('HM-2026-8006', 300_000_000, 'hung');

    const res = await app.inject({
      method: 'POST',
      url: '/api/de-xuat',
      headers: { 'x-user': 'hung' },
      payload: { so_ho_so: 'HM-2026-8006', khach_hang: 'Trần Thị B', so_tien: 300_000_000 },
    });

    expect(res.statusCode).toBe(422);
    expect(JSON.stringify(res.json())).toContain('tồn tại');
  });

it('P6: giải ngân với de_xuat_id không tồn tại', async () => {
    const res = await app.inject({
      method: 'POST',
      url: `/api/de-xuat/999999/giai-ngan`,
      payload: { so_ky: 3 },
    });
    expect(res.statusCode).toBe(404);
  });

